59	/**
60	 * Checks if a command with its arguments is known to be safe to execute
61	 * without requiring user confirmation. This is primarily used to allow
62	 * harmless, read-only commands to run silently in the macOS sandbox.
63	 *
64	 * It handles raw command execution as well as wrapped commands like `bash -c "..."` or `bash -lc "..."`.
65	 * For wrapped commands, it parses the script and ensures all individual
66	 * sub-commands are in the known-safe list and no dangerous shell operators
67	 * (like subshells or redirection) are used.
68	 *
69	 * @param args - The command and its arguments (e.g., ['ls', '-la'])
70	 * @returns true if the command is considered safe, false otherwise.
71	 */
72	export function isKnownSafeCommand(args: string[]): boolean {
73	  if (!args || args.length === 0) {
74	    return false;
75	  }
76	
77	  // Normalize zsh to bash
78	  const normalizedArgs = args.map((a) => (a === 'zsh' ? 'bash' : a));
79	
80	  if (isSafeToCallWithExec(normalizedArgs)) {
81	    return true;
82	  }
83	
84	  // Support `bash -lc "..."`
85	  if (
86	    normalizedArgs.length === 3 &&
87	    normalizedArgs[0] === 'bash' &&
88	    (normalizedArgs[1] === '-lc' || normalizedArgs[1] === '-c')
89	  ) {
90	    try {
91	      const script = normalizedArgs[2];
92	
93	      // Basic check for dangerous operators that could spawn subshells or redirect output
94	      // We allow &&, ||, |, ; but explicitly block subshells () and redirection >, >>, <
95	      if (/[()<>]/g.test(script)) {
96	        return false;
97	      }
98	
99	      const commands = splitCommands(script);
100	      if (commands.length === 0) return false;
101	
102	      return commands.every((cmd) => {
103	        const trimmed = cmd.trim();
104	        if (!trimmed) return true;
105	
106	        const parsed = shellParse(trimmed).map(extractStringFromParseEntry);
107	        if (parsed.length === 0) return true;
108	
109	        return isSafeToCallWithExec(parsed);
110	      });
111	    } catch {
112	      return false;
113	    }
114	  }
115	
116	  return false;
117	}
