export function isTrustedSystemPath(filePath: string): boolean {
  // Never trust anything inside the current working directory, even if it
  // happens to match a system location; a repo could shadow a trusted binary.
  if (isSubpath(process.cwd(), filePath)) {
    return false;
  }

  const trustedDirs: string[] = [];

  if (process.platform === 'win32') {
    for (const envVar of ['SystemRoot', 'ProgramFiles', 'ProgramFiles(x86)']) {
      const dir = process.env[envVar];
      if (dir) {
        trustedDirs.push(dir);
      }
