    trustedDirs.push(
      '/usr/bin',
      '/bin',
      '/usr/local/bin',
      '/opt/homebrew/bin',
      '/opt/homebrew/Cellar',
      '/usr/local/Cellar',
      '/usr/sbin',
      '/sbin',
    );
  }

  return trustedDirs.some((dir) => isSubpath(dir, filePath));
}

