 * Resolves the path to the ripgrep (`rg`) binary.
 *
 * The bundled vendor binary is always preferred. If it is unavailable (e.g. in
 * environments where the vendored binary was not shipped), we fall back to a
 * system-installed `rg` discovered on the PATH — but only if that binary,
 * after resolving any symlinks, resides in a trusted system directory. This
 * prevents a malicious `rg` planted in a project directory from being executed.
 *
 * @returns The resolved binary path, or null if no trusted binary was found.
 */
export async function resolveRipgrepPath(): Promise<string | null> {
  const platform = os.platform();
  const arch = os.arch();

  // Map to the correct bundled binary
  const binName = `rg-${platform}-${arch}${platform === 'win32' ? '.exe' : ''}`;

  const candidatePaths = [
    // 1. SEA runtime layout: everything is flattened into the root dir
    path.resolve(__dirname, 'vendor/ripgrep', binName),
    // 2. Dev/Dist layout: packages/core/dist/tools/ripGrep.js -> packages/core/vendor/ripgrep
    path.resolve(__dirname, '../../vendor/ripgrep', binName),
  ];

  for (const candidate of candidatePaths) {
    if (await fileExists(candidate)) {
      return candidate;
    }
  }

  // No bundled binary found; fall back to a system-installed `rg`.
  const systemPath = await resolveExecutable('rg');
  if (!systemPath) {
    return null;
  }

  try {
    const realPath = resolveToRealPath(systemPath);
    if (isTrustedSystemPath(realPath)) {
      return realPath;
    }
  } catch {
    // If we cannot resolve the real path, treat it as untrusted.
    return null;
  }

  return null;
